import{_ as t,o as a,c as r,a3 as n}from"./chunks/framework.B5WAEDB7.js";const m=JSON.parse('{"title":"Column Types","description":"All column types in ApptiveGrid, with settings, form behavior, and filter conditions.","frontmatter":{"title":"Column Types","description":"All column types in ApptiveGrid, with settings, form behavior, and filter conditions."},"headers":[],"relativePath":"en/referenz/spaltentypen.md","filePath":"en/referenz/spaltentypen.md","lastUpdated":1787319236000}'),i={name:"en/referenz/spaltentypen.md"};function l(o,e,s,d,u,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="column-types-—-reference" tabindex="-1">Column Types — Reference <a class="header-anchor" href="#column-types-—-reference" aria-label="Permalink to &quot;Column Types — Reference&quot;">​</a></h1><p>Every field in a Grid has a column type. It determines the allowed values, the display, the available filter conditions, and how the field behaves in forms.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Column Type</th><th>Short Description</th><th>In Forms</th><th>Summable</th></tr></thead><tbody><tr><td><a href="#text">Text</a></td><td>Single-line text</td><td>✓</td><td>–</td></tr><tr><td><a href="#rich-text">Rich Text</a></td><td>Text with formatting</td><td>–</td><td>–</td></tr><tr><td><a href="#number">Number</a></td><td>Whole number</td><td>✓</td><td>✓</td></tr><tr><td><a href="#decimal">Decimal</a></td><td>Number with decimal places</td><td>✓</td><td>✓</td></tr><tr><td><a href="#currency">Currency</a></td><td>Monetary amount with currency</td><td>✓</td><td>✓</td></tr><tr><td><a href="#date">Date</a></td><td>Date without time</td><td>✓</td><td>–</td></tr><tr><td><a href="#date-and-time">Date and time</a></td><td>A point in time</td><td>✓</td><td>–</td></tr><tr><td><a href="#checkmark">Checkmark</a></td><td>Yes/No</td><td>✓</td><td>–</td></tr><tr><td><a href="#single-select">Single Select</a></td><td>One option from a list</td><td>✓</td><td>–</td></tr><tr><td><a href="#multiple-select">Multiple Select</a></td><td>Several options</td><td>✓</td><td>–</td></tr><tr><td><a href="#link-record">Link record</a></td><td>Reference to one entry</td><td>✓</td><td>–</td></tr><tr><td><a href="#link-multiple-records">Link multiple records</a></td><td>References to several entries</td><td>✓</td><td>–</td></tr><tr><td><a href="#files">Files</a></td><td>File and image attachments</td><td>✓</td><td>–</td></tr><tr><td><a href="#address">Address</a></td><td>Postal address</td><td>✓</td><td>–</td></tr><tr><td><a href="#geolocation">Geolocation</a></td><td>Coordinates</td><td>✓</td><td>–</td></tr><tr><td><a href="#e-mail">E-Mail</a></td><td>E-mail address</td><td>✓</td><td>–</td></tr><tr><td><a href="#phone-number">Phone Number</a></td><td>Telephone number</td><td>✓</td><td>–</td></tr><tr><td><a href="#weblink">Weblink</a></td><td>Web address</td><td>✓</td><td>–</td></tr><tr><td><a href="#signature">Signature</a></td><td>Handwritten signature</td><td>✓</td><td>–</td></tr><tr><td><a href="#user">User</a></td><td>Reference to a person</td><td>✓</td><td>–</td></tr><tr><td><a href="#created-by">Created by</a></td><td>Who created the entry</td><td>read-only</td><td>–</td></tr><tr><td><a href="#created-at">Created at</a></td><td>When the entry was created</td><td>read-only</td><td>–</td></tr><tr><td><a href="#use-linked-value">Use linked value</a></td><td>Value from a linked entry</td><td>read-only</td><td>–</td></tr><tr><td><a href="#calculate-sum">Calculate sum</a></td><td>Sum over linked entries</td><td>read-only</td><td>–</td></tr><tr><td><a href="#formula">Formula</a></td><td>Calculated value</td><td>read-only</td><td>–</td></tr><tr><td><a href="#internal-link">Internal Link</a></td><td>Reference to a Grid, Form, Page, or Link</td><td>✓</td><td>–</td></tr></tbody></table><hr><h2 id="text-like-types" tabindex="-1">Text-like types <a class="header-anchor" href="#text-like-types" aria-label="Permalink to &quot;Text-like types&quot;">​</a></h2><h3 id="text" tabindex="-1">Text <a class="header-anchor" href="#text" aria-label="Permalink to &quot;Text&quot;">​</a></h3><p>Single-line text for names, subject lines, short notes.</p><ul><li><strong>Settings:</strong> none</li><li><strong>In the form:</strong> single-line text field; can be switched to multiple lines via the <strong>Multi-line</strong> field setting</li><li><strong>Filter:</strong> equals, does not equal, contains, does not contain, is empty, is not empty</li></ul><h3 id="rich-text" tabindex="-1">Rich Text <a class="header-anchor" href="#rich-text" aria-label="Permalink to &quot;Rich Text&quot;">​</a></h3><p>Text with formatting such as bold, lists, and headings.</p><ul><li><strong>Settings:</strong> none</li></ul><div class="warning custom-block"><p class="custom-block-title">Not available in forms</p><p>No form field exists for this type. If users need to enter longer text, use <strong>Text</strong> with the <em>Multi-line</em> field setting instead.</p></div><hr><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><h3 id="number" tabindex="-1">Number <a class="header-anchor" href="#number" aria-label="Permalink to &quot;Number&quot;">​</a></h3><p>Whole numbers for quantities, counts, positions.</p><ul><li><strong>Settings:</strong> none</li><li><strong>In the form:</strong> text field with number validation</li><li><strong>Filter:</strong> equals, does not equal, is less than, is greater than, is empty, is not empty</li><li><strong>Summable</strong> in groupings and in the summary row</li><li><strong>Error message:</strong> <em>Only numbers (0-9) are allowed</em></li></ul><h3 id="decimal" tabindex="-1">Decimal <a class="header-anchor" href="#decimal" aria-label="Permalink to &quot;Decimal&quot;">​</a></h3><p>Numbers with decimal places.</p><ul><li><strong>Settings:</strong> none</li><li><strong>Filter:</strong> same as Number</li><li><strong>Summable</strong></li><li><strong>Error message:</strong> <em>Only floating point numbers are allowed</em></li></ul><h3 id="currency" tabindex="-1">Currency <a class="header-anchor" href="#currency" aria-label="Permalink to &quot;Currency&quot;">​</a></h3><p>Monetary amounts with a currency and defined precision.</p><ul><li><strong>Settings:</strong><ul><li><strong>Currency</strong> — required, chosen from a list</li><li><strong>Decimal places</strong> — default <strong>2</strong></li></ul></li><li><strong>Display:</strong> according to the language setting, so <code>1,234.56 €</code> — or <code>1.234,56 €</code> in German</li><li><strong>Filter:</strong> same as Number</li><li><strong>Summable</strong></li></ul><div class="tip custom-block"><p class="custom-block-title">Decimal places is not its own column type</p><p><em>Decimal places</em> shows up in the interface as its own term. It&#39;s a setting of this type, not a separate column type.</p></div><hr><h2 id="date-and-time" tabindex="-1">Date and time <a class="header-anchor" href="#date-and-time" aria-label="Permalink to &quot;Date and time&quot;">​</a></h2><h3 id="date" tabindex="-1">Date <a class="header-anchor" href="#date" aria-label="Permalink to &quot;Date&quot;">​</a></h3><p>A date without a time.</p><ul><li><strong>Settings:</strong> none</li><li><strong>Filter:</strong> equals, does not equal, is before, is after, is empty, is not empty</li><li><strong>Relative options in the filter:</strong> today, tomorrow, yesterday, X days ago, in X days, exact date</li></ul><h3 id="date-and-time-1" tabindex="-1">Date and time <a class="header-anchor" href="#date-and-time-1" aria-label="Permalink to &quot;Date and time&quot;">​</a></h3><p>An exact point in time.</p><ul><li><strong>Settings:</strong> none</li><li><strong>Filter:</strong> same as Date</li><li><strong>Error message:</strong> <em>Unrecognized date format: {date}</em></li></ul><hr><h2 id="selection" tabindex="-1">Selection <a class="header-anchor" href="#selection" aria-label="Permalink to &quot;Selection&quot;">​</a></h2><h3 id="single-select" tabindex="-1">Single Select <a class="header-anchor" href="#single-select" aria-label="Permalink to &quot;Single Select&quot;">​</a></h3><p>Exactly one option from a predefined list.</p><ul><li><strong>Settings:</strong><ul><li><strong>Option list</strong> — at least one option required</li><li><strong>Allow other input</strong> — also permits free text</li></ul></li><li><strong>In the form:</strong> component type <em>Dropdown</em> or <em>List</em></li><li><strong>Filter:</strong> equals, does not equal, is empty, is not empty</li><li><strong>Error messages:</strong> <em>The option must not be empty</em>, <em>The option must not be a duplicate</em></li></ul><p>This type is a prerequisite for the <a href="/en/seiten/auswertungen">donut chart block</a> and the usual basis for Kanban columns.</p><h3 id="multiple-select" tabindex="-1">Multiple Select <a class="header-anchor" href="#multiple-select" aria-label="Permalink to &quot;Multiple Select&quot;">​</a></h3><p>Any number of options from a list.</p><ul><li><strong>Settings:</strong> same as Single Select</li><li><strong>In the form:</strong> component type <em>Dropdown</em> or <em>List</em>, with multiple selection</li><li><strong>Filter:</strong> additionally <em>includes any of</em>, <em>includes none of</em>, <em>includes all of</em></li></ul><hr><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><h3 id="link-record" tabindex="-1">Link record <a class="header-anchor" href="#link-record" aria-label="Permalink to &quot;Link record&quot;">​</a></h3><p>A reference to exactly one entry in another Grid.</p><ul><li><strong>Settings:</strong> choose the target view (<em>Select a Grid View that entries are linked from</em>)</li><li><strong>In the form:</strong> selection dialog over the entries of the target Grid</li><li><strong>Filter:</strong> is empty, is not empty</li></ul><div class="warning custom-block"><p class="custom-block-title">Nested links</p><p>ApptiveGrid reports <em>Links to Grids that are already linked elsewhere are not yet possible.</em> This means you cannot stack links arbitrarily deep. Plan your data model to stay flat.</p></div><h3 id="link-multiple-records" tabindex="-1">Link multiple records <a class="header-anchor" href="#link-multiple-records" aria-label="Permalink to &quot;Link multiple records&quot;">​</a></h3><p>References to any number of entries in another Grid.</p><ul><li><strong>Settings:</strong> same as above</li><li><strong>Prerequisite for:</strong> <a href="#calculate-sum">Calculate sum</a></li></ul><h3 id="internal-link" tabindex="-1">Internal Link <a class="header-anchor" href="#internal-link" aria-label="Permalink to &quot;Internal Link&quot;">​</a></h3><p>A reference to an object within ApptiveGrid.</p><ul><li><strong>Settings:</strong> allowed target types — <strong>Grid</strong>, <strong>Form</strong>, <strong>Page</strong>, <strong>Link</strong>. By default all four are allowed.</li><li><strong>In the form:</strong> selection field for resources</li><li><strong>Filter:</strong> is empty, is not empty</li></ul><p>Useful for linking directly from an entry to a form or a portal.</p><div class="tip custom-block"><p class="custom-block-title">Target type &quot;Link&quot; — shown as a button, tied to the entry</p><p>If the field points to a <strong>Link</strong> (the sharing link of a form or the start link of a Flow), ApptiveGrid displays the value as a <strong>button</strong> instead of text. Clicking it opens the target in an overlay and passes along the <strong>URI and the ID of the entry</strong> as URL parameters — so the target knows which row the click came from.</p><p>This lets you trigger Flows from an entry that are meant to act on exactly that entry — for example, an approval process or an action that updates the record.</p><p>→ <a href="/en/grids/flow-button">Start a Flow from an entry via a button</a></p></div><hr><h2 id="calculated-fields" tabindex="-1">Calculated fields <a class="header-anchor" href="#calculated-fields" aria-label="Permalink to &quot;Calculated fields&quot;">​</a></h2><p>All three types are <strong>read-only</strong> and are <strong>not available in forms</strong>.</p><h3 id="use-linked-value" tabindex="-1">Use linked value <a class="header-anchor" href="#use-linked-value" aria-label="Permalink to &quot;Use linked value&quot;">​</a></h3><p>Pulls a value from a linked entry into the current Grid.</p><ul><li><strong>Settings:</strong><ul><li><strong>Link field</strong> — which link column is used</li><li><strong>Target field</strong> — which field is retrieved from the linked entry</li></ul></li><li><strong>Prerequisite:</strong> a column of type <em>Link record</em></li></ul><div class="warning custom-block"><p class="custom-block-title">Cannot be used as a Flow condition</p><p>This type cannot be selected as the triggering field in the <em>Entry changed</em> Flow trigger.</p></div><h3 id="calculate-sum" tabindex="-1">Calculate sum <a class="header-anchor" href="#calculate-sum" aria-label="Permalink to &quot;Calculate sum&quot;">​</a></h3><p>Sums a numeric field across all linked entries.</p><ul><li><strong>Settings:</strong><ul><li><strong>Link field</strong> — a column of type <em>Link multiple records</em></li><li><strong>Target field</strong> — the numeric field to sum</li></ul></li><li><strong>Prerequisite:</strong> a column of type <em>Link multiple records</em></li></ul><p>Typical case: an &quot;Invoices&quot; Grid sums the amounts of all linked &quot;Line items.&quot;</p><h3 id="formula" tabindex="-1">Formula <a class="header-anchor" href="#formula" aria-label="Permalink to &quot;Formula&quot;">​</a></h3><p>Calculates a value from an expression.</p><ul><li><strong>Settings:</strong><ul><li><strong>Expression</strong> — written in ApptiveScript, see the <a href="/en/referenz/apptivescript-funktionen">function reference</a></li><li><strong>Result type</strong> — the type the result should have</li></ul></li><li><strong>Editor:</strong> shows a <em>sample result</em> and the determined type</li></ul><div class="warning custom-block"><p class="custom-block-title">Cannot be used as a Flow condition</p><p>Like <em>Use linked value</em>, this type is also unavailable as the triggering field in the <em>Entry changed</em> trigger.</p></div><hr><h2 id="contact-and-location" tabindex="-1">Contact and location <a class="header-anchor" href="#contact-and-location" aria-label="Permalink to &quot;Contact and location&quot;">​</a></h2><h3 id="e-mail" tabindex="-1">E-Mail <a class="header-anchor" href="#e-mail" aria-label="Permalink to &quot;E-Mail&quot;">​</a></h3><ul><li><strong>Settings:</strong> none</li><li><strong>Error message:</strong> <em>A valid e-mail address is required</em></li></ul><h3 id="phone-number" tabindex="-1">Phone Number <a class="header-anchor" href="#phone-number" aria-label="Permalink to &quot;Phone Number&quot;">​</a></h3><ul><li><strong>Settings:</strong> none</li><li><strong>Error messages:</strong> <em>Please enter a valid phone number</em>, <em>An international dialing code is required (e.g. +49)</em></li></ul><div class="tip custom-block"><p class="custom-block-title">International dialing code</p><p>Phone numbers need a country code. Point this out with a field description in forms, or incorrect entries will pile up.</p></div><h3 id="weblink" tabindex="-1">Weblink <a class="header-anchor" href="#weblink" aria-label="Permalink to &quot;Weblink&quot;">​</a></h3><ul><li><strong>Settings:</strong> none</li><li><strong>Error message:</strong> <em>Please enter a valid URL</em></li></ul><h3 id="address" tabindex="-1">Address <a class="header-anchor" href="#address" aria-label="Permalink to &quot;Address&quot;">​</a></h3><p>A structured postal address made up of country, address line 1 and 2, city, and further subfields. Also includes coordinates.</p><ul><li><strong>Settings:</strong> none</li><li><strong>Error message:</strong> <em>Please fill in the required subfields</em></li></ul><div class="tip custom-block"><p class="custom-block-title">Geocoding depends on your plan</p><p>Automatically determining coordinates from an address — and therefore showing it as a map marker — is only available on the highest plan.</p></div><h3 id="geolocation" tabindex="-1">Geolocation <a class="header-anchor" href="#geolocation" aria-label="Permalink to &quot;Geolocation&quot;">​</a></h3><p>A pair of coordinates.</p><ul><li><strong>Settings:</strong> none</li><li><strong>Input format:</strong> <code>latitude,longitude</code></li><li><strong>Error message:</strong> <em>Must be in the format Latitude, Longitude (e.g. 50.12,6.543)</em></li></ul><hr><h2 id="files-and-signature" tabindex="-1">Files and signature <a class="header-anchor" href="#files-and-signature" aria-label="Permalink to &quot;Files and signature&quot;">​</a></h2><h3 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h3><p>Any number of file and image attachments.</p><ul><li><strong>Settings:</strong> none on the field itself</li><li><strong>In the form:</strong> component type <em>Select file</em>; optionally <strong>Only allow adding files</strong>, so existing attachments cannot be deleted</li><li><strong>Limit:</strong> the maximum file size depends on your plan</li></ul><h3 id="signature" tabindex="-1">Signature <a class="header-anchor" href="#signature" aria-label="Permalink to &quot;Signature&quot;">​</a></h3><p>A signature drawn with a mouse or a finger.</p><ul><li><strong>Settings:</strong> none</li><li><strong>In the form:</strong> drawing surface with the hint <em>Tap here to sign</em></li></ul><hr><h2 id="person-related-types" tabindex="-1">Person-related types <a class="header-anchor" href="#person-related-types" aria-label="Permalink to &quot;Person-related types&quot;">​</a></h2><h3 id="user" tabindex="-1">User <a class="header-anchor" href="#user" aria-label="Permalink to &quot;User&quot;">​</a></h3><p>A reference to a person.</p><ul><li><strong>Settings:</strong> none</li><li><strong>Filter:</strong> <em>is</em>, <em>is not</em>, plus the expression <em>current user</em></li></ul><h3 id="created-by" tabindex="-1">Created by <a class="header-anchor" href="#created-by" aria-label="Permalink to &quot;Created by&quot;">​</a></h3><p>Who created the entry. Set automatically and cannot be changed.</p><p>Besides people, possible values also include <strong>Form link</strong> (the entry came in via a form) and <strong>API Credentials</strong> (the entry came in via the API).</p><ul><li><strong>Filter:</strong> <em>is</em>, <em>is not</em>, plus <em>current user</em></li></ul><h3 id="created-at" tabindex="-1">Created at <a class="header-anchor" href="#created-at" aria-label="Permalink to &quot;Created at&quot;">​</a></h3><p>When the entry was created. Set automatically and cannot be changed.</p><ul><li><strong>Filter:</strong> same as <em>Date and time</em></li></ul><div class="warning custom-block"><p class="custom-block-title">Cannot be used as a Flow condition</p><p>This type is also unavailable as the triggering field in the <em>Entry changed</em> trigger — it doesn&#39;t change after creation anyway.</p></div><hr><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/en/grids/felder">Creating and editing fields</a></li><li><a href="/en/grids/verknuepfungen">Linking Grids</a></li><li><a href="/en/grids/berechnete-felder">Calculated fields</a></li><li><a href="/en/referenz/filterbedingungen">Filter conditions</a></li></ul>',111)])])}const g=t(i,[["render",l]]);export{m as __pageData,g as default};
